// Content validation shared by the Admin Studio (browser) and the Cloudflare Worker.
// Pure functions: take a content object { characters, npcs, items, quests, dialogues, maps, shop, achievements, config }
// and return { errors: [], warnings: [] }. Nothing generated by the AI is published unless errors is empty.

export const STEP_TYPES = ['talk', 'collect', 'minigame', 'goto', 'use', 'cutscene', 'interact', 'choice', 'teleport'];
export const MINIGAMES = ['timing', 'memory', 'reaction', 'quiz', 'drive', 'sequence'];
export const ABILITIES = ['dash', 'sniff', 'charm', 'fix'];
export const ITEM_TYPES = ['quest', 'consumable', 'collectible', 'key', 'outfit', 'upgrade', 'character'];
export const HAIR_STYLES = ['short', 'long', 'curly', 'bun', 'ponytail', 'bald'];
export const ACCESSORIES = ['none', 'glasses', 'catglasses', 'sunglasses', 'round', 'beard', 'both'];
export const EXTRAS = ['freckles', 'earrings', 'necklace', 'bowtie', 'headphones', 'mustache'];
export const ICONS = ['food', 'key', 'gem', 'book', 'hat', 'shoe', 'potion', 'toy', 'star', 'phone', 'remote', 'ticket', 'shirt', 'coin', 'default'];
export const PROP_TYPES = ['tree', 'bush', 'rock', 'table', 'sofa', 'bed', 'fridge', 'stove', 'tv', 'plant', 'sign', 'chest', 'shelf', 'counter', 'umbrella', 'lamp', 'door', 'mat', 'boat', 'deer', 'car', 'suitcase', 'salad', 'crib', 'album', 'ship', 'desk', 'lantern', 'torii', 'podium'];
const COLOR = /^#[0-9a-fA-F]{6}$/;
const ID = /^[a-z][a-z0-9_]{1,40}$/;
const EFFECTS = ['coins', 'xp', 'item', 'giveOnce', 'flag', 'shop', 'teleport', 'ending', 'toast'];

export function validateLook(look, where, E) {
  if (!look || typeof look !== 'object') { E.push(`${where}: חסר מראה (look)`); return; }
  for (const k of ['skin', 'hair', 'shirt', 'pants']) if (!COLOR.test(look[k] || '')) E.push(`${where}: צבע לא תקין ב-${k}`);
  if (look.hat && !COLOR.test(look.hat)) E.push(`${where}: צבע כובע לא תקין`);
  if (look.eyes && !COLOR.test(look.eyes)) E.push(`${where}: צבע עיניים לא תקין`);
  for (const x of look.extras || []) if (!EXTRAS.includes(x)) E.push(`${where}: אביזר נוסף לא מוכר (${x})`);
  if (!HAIR_STYLES.includes(look.hairStyle)) E.push(`${where}: סגנון שיער לא מוכר (${look.hairStyle})`);
  if (look.accessory && !ACCESSORIES.includes(look.accessory)) E.push(`${where}: אביזר לא מוכר (${look.accessory})`);
}

function textOk(t) { return typeof t === 'string' && t.trim().length > 0 && t.length < 600; }
function checkGenderTemplates(t, where, W) {
  const opens = (t.match(/\{/g) || []).length, closes = (t.match(/\}/g) || []).length;
  if (opens !== closes) W.push(`${where}: סוגריים מסולסלים לא מאוזנים`);
  for (const m of t.matchAll(/\{([^{}]*)\}/g)) if (!/^(f:[^|}]*\|m:[^}]*|m:[^|}]*\|f:[^}]*|self:[^|}]*\|other:[^}]*|name)$/.test(m[1])) W.push(`${where}: תבנית מגדר לא תקינה {${m[1]}}`);
}

export function validateContent(c) {
  const E = [], W = [];
  const chars = c.characters || {}, npcs = c.npcs || {}, items = c.items || {}, quests = c.quests || {}, dialogues = c.dialogues || {}, maps = c.maps || {};

  for (const [id, ch] of Object.entries(chars)) {
    if (!ID.test(id)) E.push(`דמות ${id}: מזהה לא תקין (אותיות קטנות באנגלית, ספרות וקו תחתון)`);
    if (!textOk(ch.name)) E.push(`דמות ${id}: חסר שם`);
    if (!['m', 'f'].includes(ch.gender)) E.push(`דמות ${id}: חסר מגדר (m/f)`);
    validateLook(ch.look, `דמות ${id}`, E);
    if (!ch.ability || !ABILITIES.includes(ch.ability.type)) E.push(`דמות ${id}: יכולת לא מוכרת`);
  }
  for (const [id, n] of Object.entries(npcs)) {
    if (!ID.test(id)) E.push(`דמות משנית ${id}: מזהה לא תקין`);
    if (!textOk(n.name)) E.push(`דמות משנית ${id}: חסר שם`);
    validateLook(n.look, `דמות משנית ${id}`, E);
    if (n.character && !chars[n.character]) E.push(`דמות משנית ${id}: הדמות הראשית לא קיימת (${n.character})`);
    if (n.phrases && !(n.phrases.length >= 1 && n.phrases.every((t) => typeof t === 'string' ? textOk(t) : textOk(t.text)))) E.push(`דמות משנית ${id}: משפטים לא תקינים`);
    for (const d of n.dialogues || []) if (!dialogues[d.id]) E.push(`דמות משנית ${id}: דיאלוג חסר (${d.id})`);
    if (n.shop && !(c.shop || {})[n.shop]) W.push(`דמות משנית ${id}: חנות ללא רשימת מוצרים (${n.shop})`);
  }
  for (const [id, it] of Object.entries(items)) {
    if (!ID.test(id)) E.push(`פריט ${id}: מזהה לא תקין`);
    if (!textOk(it.name)) E.push(`פריט ${id}: חסר שם`);
    if (!ITEM_TYPES.includes(it.type)) E.push(`פריט ${id}: סוג לא מוכר (${it.type})`);
    if (it.icon && !ICONS.includes(it.icon)) W.push(`פריט ${id}: אייקון לא מוכר (${it.icon})`);
    if (it.color && !COLOR.test(it.color)) E.push(`פריט ${id}: צבע לא תקין`);
    if (it.price != null && (!Number.isFinite(it.price) || it.price < 0 || it.price > 5000)) E.push(`פריט ${id}: מחיר לא סביר`);
    if (it.type === 'outfit') validateLook({ skin: '#000000', hair: '#000000', pants: '#000000', shirt: '#000000', hairStyle: 'short', ...(it.look || {}) }, `פריט ${id}`, E);
  }
  const checkLines = (lines, where) => {
    if (!Array.isArray(lines) || !lines.length) { E.push(`${where}: אין שורות דיאלוג`); return; }
    for (const [i, ln] of lines.entries()) {
      if (!textOk(ln.text)) E.push(`${where} שורה ${i + 1}: טקסט ריק או ארוך מדי`);
      else checkGenderTemplates(ln.text, `${where} שורה ${i + 1}`, W);
      const who = ln.who || 'narrator';
      if (!['player', 'narrator'].includes(who) && !npcs[who] && !chars[who]) E.push(`${where} שורה ${i + 1}: דובר לא קיים (${who})`);
    }
  };
  const checkEffects = (effs, where) => {
    for (const e of effs || []) {
      if (!EFFECTS.includes(e.type)) E.push(`${where}: אפקט לא מוכר (${e.type})`);
      if (e.type === 'item' && !items[e.id]) E.push(`${where}: פריט לא קיים (${e.id})`);
      if (e.type === 'giveOnce' && !items[e.item]) E.push(`${where}: פריט לא קיים (${e.item})`);
      if ((e.type === 'coins' || e.type === 'xp') && !(Math.abs(e.n) <= 1000)) E.push(`${where}: כמות לא סבירה`);
      if (e.type === 'teleport' && !maps[e.map]) E.push(`${where}: מפה לא קיימת (${e.map})`);
    }
  };
  for (const [id, d] of Object.entries(dialogues)) {
    if (!ID.test(id)) E.push(`דיאלוג ${id}: מזהה לא תקין`);
    if (!d.start) E.push(`דיאלוג ${id}: חסר צומת start`);
    for (const [nid, node] of Object.entries(d)) {
      const w = `דיאלוג ${id}/${nid}`;
      if (node.text != null) { if (!textOk(node.text)) E.push(`${w}: טקסט לא תקין`); else checkGenderTemplates(node.text, w, W); }
      if (node.who && !['player', 'narrator'].includes(node.who) && !npcs[node.who] && !chars[node.who]) E.push(`${w}: דובר לא קיים (${node.who})`);
      for (const b of node.branch || []) if (b.next && !d[b.next]) E.push(`${w}: מעבר לצומת לא קיים (${b.next})`);
      for (const ch of node.choices || []) { if (ch.next && !d[ch.next]) E.push(`${w}: בחירה מובילה לצומת לא קיים (${ch.next})`); checkEffects(ch.effects, w); }
      if (node.next && !d[node.next]) E.push(`${w}: next לא קיים (${node.next})`);
      checkEffects(node.effects, w);
    }
  }
  for (const [id, q] of Object.entries(quests)) {
    const w = `משימה ${id}`;
    if (!ID.test(id)) E.push(`${w}: מזהה לא תקין`);
    if (q.id !== id) E.push(`${w}: id לא תואם למפתח`);
    if (!textOk(q.title)) E.push(`${w}: חסר שם`);
    if (q.giver && !npcs[q.giver]) E.push(`${w}: נותן המשימה לא קיים (${q.giver})`);
    if (q.scene && !maps[q.scene.map]) E.push(`${w}: מפת הסצנה לא קיימת (${q.scene.map})`);
    for (const mm of q.maps || []) if (!maps[mm]) E.push(`${w}: מפה לא קיימת (${mm})`);
    if (q.char && !chars[q.char]) E.push(`${w}: דמות נדרשת לא קיימת (${q.char})`);
    if (q.protagonist && !chars[q.protagonist]) E.push(`${w}: גיבור הסיפור לא קיים (${q.protagonist})`);
    for (const c of q.cast || []) if (!chars[c] && !npcs[c]) E.push(`${w}: דמות בסיפור לא קיימת (${c})`);
    if (q.scene) { if (!q.callers?.length) E.push(`${w}: חסרים callers (מי קורא לשחקן)`); for (const k of ['missionSelf', 'missionOther', 'missionPlayer']) if (q.scene && !Array.isArray(q[k])) E.push(`${w}: חסר ${k}`); else if (q.scene) checkLines((q[k] || []).map((t) => ({ who: 'narrator', text: t })), `${w} (${k})`); }
    if (q.offer) checkLines(q.offer, `${w} (הצעה)`); else if (q.giver) E.push(`${w}: חסרה הצעת משימה (offer)`);
    if (!Array.isArray(q.steps) || !q.steps.length) { E.push(`${w}: אין שלבים`); continue; }
    q.steps.forEach((s, i) => {
      const sw = `${w} שלב ${i + 1}`;
      if (!STEP_TYPES.includes(s.type)) { E.push(`${sw}: סוג שלב לא מוכר (${s.type})`); return; }
      if (!textOk(s.text) && s.type !== 'cutscene' && s.type !== 'teleport' && s.type !== 'choice') E.push(`${sw}: חסר טקסט יעד`);
      if (s.lines) checkLines(s.lines, sw);
      if (s.type === 'talk' && !npcs[s.npc]) E.push(`${sw}: דמות לא קיימת (${s.npc})`);
      if (q.cast && s.type === 'talk' && npcs[s.npc]?.character) E.push(`${sw}: אי אפשר לשלב שיחה אינטראקטיבית עם בן משפחה (${s.npc}) - השחקן עלול להיות אותו אדם. השתמשו ב-cutscene`);
      if (s.type === 'cutscene') checkLines(s.lines, sw);
      if (s.type === 'teleport' && !maps[s.map]) E.push(`${sw}: מפה לא קיימת (${s.map})`);
      if (s.type === 'interact' && !Object.values(maps).some((m) => (m.props || []).some((p) => p.id === s.target))) E.push(`${sw}: אובייקט לא קיים (${s.target})`);
      if (s.type === 'choice') { if (!textOk(s.question) || !Array.isArray(s.options) || s.options.length < 2 || !s.options.some((o) => o.correct)) E.push(`${sw}: בחירה חייבת שאלה, 2 אפשרויות לפחות ותשובה נכונה אחת`); else s.options.forEach((o) => { if (!textOk(o.text)) E.push(`${sw}: אפשרות ריקה`); }); }
      if (s.timeLimit != null && !(s.timeLimit >= 5 && s.timeLimit <= 300)) E.push(`${sw}: מגבלת זמן לא סבירה`);
      if (s.type === 'collect' && !items[s.item]) E.push(`${sw}: פריט לא קיים (${s.item})`);
      if (s.type === 'goto' && !maps[s.map]) E.push(`${sw}: מפה לא קיימת (${s.map})`);
      if (s.type === 'minigame') {
        if (!MINIGAMES.includes(s.game)) E.push(`${sw}: משחקון לא מוכר (${s.game})`);
        const known = s.auto || npcs[s.at] || Object.values(maps).some((m) => (m.props || []).some((p) => p.id === s.at));
        if (!known) E.push(`${sw}: מקום המשחקון לא קיים (${s.at})`);
        if (s.game === 'quiz' && !(s.config?.questions || []).length) E.push(`${sw}: חידון בלי שאלות`);
      }
      if (s.type === 'use' && !Object.values(maps).some((m) => (m.props || []).some((p) => p.id === s.target))) E.push(`${sw}: אובייקט לא קיים (${s.target})`);
      if (s.give && !items[s.give]) E.push(`${sw}: פריט לא קיים (${s.give})`);
      if (s.consume && !items[s.consume]) E.push(`${sw}: פריט לא קיים (${s.consume})`);
    });
    const r = q.reward || {};
    if (r.coins != null && !(r.coins >= 0 && r.coins <= 500)) E.push(`${w}: פרס מטבעות לא סביר (${r.coins})`);
    if (r.xp != null && !(r.xp >= 0 && r.xp <= 500)) E.push(`${w}: פרס ניסיון לא סביר (${r.xp})`);
    for (const it of r.items || []) if (!items[it]) E.push(`${w}: פריט פרס לא קיים (${it})`);
    if (r.shard && !(r.shard.id && textOk(r.shard.title) && textOk(r.shard.story))) E.push(`${w}: רסיס זיכרון חסר מזהה/כותרת/סיפור`);
    for (const tpl of [q.title, q.summary]) if (tpl) checkGenderTemplates(tpl, w, W);
  }
  for (const [id, m] of Object.entries(maps)) {
    const w = `מפה ${id}`;
    const rows = m.tiles || [];
    if (!rows.length || rows.some((r) => r.length !== rows[0].length)) E.push(`${w}: מפה לא מלבנית`);
    for (const r of rows) for (const ch of r) if (!m.legend?.[ch]) { E.push(`${w}: תו לא מוגדר במקרא (${ch})`); break; }
    for (const n of m.npcs || []) if (!npcs[n.id]) E.push(`${w}: דמות משנית לא קיימת (${n.id})`);
    if (m.gen) {   // scenes built for a generated story: everything in them must be written for THIS scene
      for (const n of m.npcs || []) if (!n.gives && !(Array.isArray(n.phrases) && n.phrases.length && n.phrases.every(textOk))) E.push(`${w}: לדמות ${n.id} חסרים משפטים ייחודיים לסצנה (phrases), גם אם זו דמות ממוחזרת`);
      for (const p of m.props || []) if (p.id !== 'exit' && !p.deco && !p.gives && !p.ability && !textOk([].concat(p.interact?.text || '')[0])) E.push(`${w}: לאובייקט ${p.id || p.type} חסר טקסט אינטראקציה לסצנה (text)`);
    }
    for (const p of m.props || []) { if (!PROP_TYPES.includes(p.type)) E.push(`${w}: סוג אובייקט לא מוכר (${p.type})`); if (p.gives && !items[p.gives]) E.push(`${w}: פריט לא קיים (${p.gives})`); }
    for (const d of m.doors || []) if (!maps[d.to]) E.push(`${w}: דלת למפה לא קיימת (${d.to})`);
    for (const p of m.pickups || []) if (!items[p.item]) E.push(`${w}: פריט לאיסוף לא קיים (${p.item})`);
    for (const n of m.npcs || []) if (!(n.x >= 0 && n.y >= 0 && n.y < rows.length && n.x < (rows[0] || '').length)) E.push(`${w}: דמות מחוץ למפה (${n.id})`);
  }
  const shardCount = Object.values(quests).filter((q) => q.reward?.shard).length;
  if (c.config && c.config.finalShards > shardCount) W.push(`config.finalShards (${c.config.finalShards}) גדול ממספר הרסיסים הקיימים (${shardCount}) - לא ניתן יהיה לסיים את המשחק`);
  for (const [sid, list] of Object.entries(c.shop || {})) for (const it of list) if (!items[it]) E.push(`חנות ${sid}: פריט לא קיים (${it})`);
  return { errors: E, warnings: W };
}

/** Merge an AI bundle (new quests/dialogues/npcs/items/...) into content without overwriting existing ids. */
export function mergeBundle(content, bundle) {
  const out = JSON.parse(JSON.stringify(content));
  const conflicts = [];
  for (const kind of ['quests', 'dialogues', 'npcs', 'items', 'achievements', 'maps']) {
    const src = bundle[kind]; if (!src) continue;
    const entries = Array.isArray(src) ? src.map((o) => [o.id, o]) : Object.entries(src);
    out[kind] ||= {};
    for (const [id, obj] of entries) {
      if (out[kind][id]) { conflicts.push(`${kind}/${id}`); continue; }
      out[kind][id] = obj;
    }
  }
  for (const [shopId, list] of Object.entries(bundle.shop || {})) { out.shop[shopId] = [...new Set([...(out.shop[shopId] || []), ...list])]; }
  return { content: out, conflicts };
}
